2	// Cyrus USERNAME: DB side (claim, change, availability, author-tag lookups). Rules live in ./username.ts.
3	import { randomBytes } from "node:crypto";
4	import { cyrusDb } from "../cyrus/db";
5	import { UNNAMED_AUTHOR, holdUntil, mayChangeUsername, validateUsername } from "./username";
6	
7	export type UsernameState = { username: string | null; usernameKey: string | null; handle: string | null; setAt: string | null; canChange: boolean; nextChangeAt: string | null };
8	
9	export async function usernameStateFor(userId: string): Promise<UsernameState> {
10	  const c = await cyrusDb.cyrusCreator.findUnique({ where: { userId } });
11	  const d = mayChangeUsername(c?.usernameSetAt ?? null);
12	  return { username: c?.username ?? null, usernameKey: c?.usernameKey ?? null, handle: c?.handle ?? null, setAt: c?.usernameSetAt?.toISOString() ?? null, canChange: d.ok, nextChangeAt: d.ok ? null : d.nextAt };
13	}
14	
15	/** Has this account chosen its author tag? (the first-run gate). */
16	export async function hasUsername(userId: string): Promise<boolean> {
17	  const c = await cyrusDb.cyrusCreator.findUnique({ where: { userId }, select: { usernameKey: true } });
18	  return !!c?.usernameKey;
19	}
20	
21	export type Availability = { ok: true; display: string; key: string } | { ok: false; message: string; code: string };
22	
23	/** Valid AND free for this account (own current name counts as free; a hold by someone else blocks it). */
24	export async function checkAvailability(raw: unknown, forUserId: string | null): Promise<Availability> {
25	  const v = validateUsername(raw);
26	  if (!v.ok) return { ok: false, code: v.code, message: v.message };
27	  const [creator, handleOwner, hold] = await Promise.all([
28	    cyrusDb.cyrusCreator.findUnique({ where: { usernameKey: v.key }, select: { userId: true } }),
29	    cyrusDb.cyrusCreator.findUnique({ where: { handle: v.key }, select: { userId: true } }),
30	    cyrusDb.cyrusUsernameHold.findUnique({ where: { usernameKey: v.key } }),
31	  ]);
32	  if (creator && creator.userId !== forUserId) return { ok: false, code: "taken", message: "That username is taken." };
33	  if (handleOwner && handleOwner.userId !== forUserId) return { ok: false, code: "taken", message: "That username is taken." };
34	  if (hold && hold.reservedUntil > new Date() && hold.userId !== forUserId) return { ok: false, code: "held", message: "That username is not available." };
35	  return { ok: true, display: v.display, key: v.key };
36	}
37	
38	export type SetResult = { ok: true; username: string } | { ok: false; code: string; message: string };
39	
40	/** Claim (first time) or change the username. The unique index is the final arbiter; a lost race reads as "taken". */
41	export async function setUsername(userId: string, raw: unknown): Promise<SetResult> {
42	  const a = await checkAvailability(raw, userId);
43	  if (!a.ok) return a;
44	  const cur = await cyrusDb.cyrusCreator.findUnique({ where: { userId } });
45	  if (cur?.usernameKey === a.key) {
46	    // same name, maybe a case change: allowed any time, no hold, no wait
47	    if (cur.username !== a.display) await cyrusDb.cyrusCreator.update({ where: { userId }, data: { username: a.display } });
48	    return { ok: true, username: a.display };
49	  }
50	  const gate = mayChangeUsername(cur?.usernameSetAt ?? null);
51	  if (!gate.ok) return { ok: false, code: "too-soon", message: gate.message };
52	  const now = new Date();
53	  try {
54	    await cyrusDb.$transaction(async (tx) => {
55	      if (cur?.usernameKey) {
56	        await tx.cyrusUsernameHold.upsert({ where: { usernameKey: cur.usernameKey }, create: { usernameKey: cur.usernameKey, userId, releasedAt: now, reservedUntil: holdUntil(now) }, update: { userId, releasedAt: now, reservedUntil: holdUntil(now) } });
57	      }
58	      // taking a name this account itself released earlier: drop its own hold
59	      await tx.cyrusUsernameHold.deleteMany({ where: { usernameKey: a.key, userId } });
60	      if (cur) await tx.cyrusCreator.update({ where: { userId }, data: { username: a.display, usernameKey: a.key, usernameSetAt: now, handle: a.key } });
61	      else await tx.cyrusCreator.create({ data: { userId, handle: a.key, username: a.display, usernameKey: a.key, usernameSetAt: now } });
62	    });
63	  } catch {
64	    return { ok: false, code: "taken", message: "That username was just taken. Try another." };
65	  }
66	  return { ok: true, username: a.display };
67	}
