195	// Cyrus USERNAME first-run gate switch. ON by default (the owner requires it before anyone uses Cyrus);
196	// CYRUS_USERNAME_REQUIRED=0 is the emergency kill switch only (e.g. if the Cyrus DB column is not pushed yet).
197	export const USERNAME_REQUIRED_ENV = "CYRUS_USERNAME_REQUIRED";
198	export const usernameRequired = (env: Record<string, string | undefined> = process.env) => env[USERNAME_REQUIRED_ENV] !== "0";
199	=== app/api/cyrus/username/route.ts
200	// Cyrus USERNAME (author tag) API, shared by both hosts (nxeon.cloud portal and cyrus.my).
201	//   GET                 -> { required, username, canChange, nextChangeAt, suggestion }
202	//   GET ?name=<candidate> -> live availability { ok, message?, code?, key?, display? } (rate limited per account and per IP)
203	//   POST { username }   -> claim / change. 404 unless the account may use Cyrus (the username itself is not required here).
204	// Same-origin only for POST. Never reveals who holds a name. Logic: lib/cyrus-mods/username*.ts.
205	import { modBuilderUserPendingUsername } from "@/lib/modbuilder/access";
206	import { checkRateLimit, clientIp } from "@/lib/rate-limit";
207	import { usernameRequired } from "@/lib/cyrus-mods/username-gate";
208	import { checkAvailability, setUsername, suggestUsername, usernameStateFor } from "@/lib/cyrus-mods/username-store";
209	
210	export const runtime = "nodejs";
211	export const dynamic = "force-dynamic";
212	
213	const json = (status: number, body: unknown, extra: Record<string, string> = {}) =>
214	  new Response(JSON.stringify(body), { status, headers: { "content-type": "application/json", "cache-control": "no-store", ...extra } });
215	
216	export async function GET(req: Request) {
217	  const user = await modBuilderUserPendingUsername().catch(() => null);
218	  if (!user) return json(404, { error: "Not found" });
219	  const name = new URL(req.url).searchParams.get("name");
220	  if (name === null) {
221	    const [state, suggestion] = await Promise.all([usernameStateFor(user.id), suggestUsername().catch(() => null)]);
222	    return json(200, { required: usernameRequired(), username: state.username, canChange: state.canChange, nextChangeAt: state.nextChangeAt, suggestion: state.username ? null : suggestion });
223	  }
224	  const rl = checkRateLimit(`cyrus-username-check:${user.id}`, { max: 40, windowMs: 60_000 });
225	  const rlIp = checkRateLimit(`cyrus-username-check-ip:${clientIp(req)}`, { max: 120, windowMs: 60_000 });
226	  if (!rl.ok || !rlIp.ok) return json(429, { error: "Too many checks. Wait a moment." }, { "retry-after": String(Math.max(rl.retryAfterSec, rlIp.retryAfterSec, 1)) });
227	  const a = await checkAvailability(name.slice(0, 64), user.id).catch(() => null);
228	  if (!a) return json(503, { error: "Could not check right now." });
229	  return json(200, a.ok ? { ok: true, display: a.display, key: a.key } : { ok: false, code: a.code, message: a.message });
230	}
231	
232	export async function POST(req: Request) {
233	  const user = await modBuilderUserPendingUsername().catch(() => null);
234	  if (!user) return json(404, { error: "Not found" });
235	  const origin = req.headers.get("origin");
236	  if (origin && origin !== new URL(req.url).origin) return json(403, { error: "cross-site" });
237	  const rl = checkRateLimit(`cyrus-username-set:${user.id}`, { max: 10, windowMs: 10 * 60_000 });
238	  if (!rl.ok) return json(429, { error: "Too many attempts. Wait a few minutes." }, { "retry-after": String(Math.max(rl.retryAfterSec, 1)) });
239	  let b: { username?: unknown } = {};
240	  try { b = (await req.json()) as typeof b; } catch { return json(400, { error: "bad json" }); }
241	  const r = await setUsername(user.id, b.username).catch(() => null);
242	  if (!r) return json(503, { error: "Could not save right now. Try again." });
243	  return r.ok ? json(200, { ok: true, username: r.username }) : json(r.code === "too-soon" ? 429 : 409, { ok: false, code: r.code, message: r.message });
244	}
