        <li>{creating ? "Your Cyrus account is a Nxeon account: one sign-in for cyrus.my and nxeon.cloud." : `Cyrus (${new URL(cfg.cyrusOrigin).host}) will use your Nxeon account ${user!.email}.`}</li>
