import { maybeReconcileUser, planPrices } from "./billing";
import { rolloverRulesCopy, serverGrantRulesCopy } from "./rollover";
import { historyLabel, type TokenHistory, type TokenState } from "./view";
import { walletPayEnabled } from "./purchase";

// Stripe is the host's (host.billing.stripe); same rule as lib/stripe stripeConfigured inside Nxeon.
const stripeConfigured = () => !!getHost().billing.stripe?.configured();

/** r44: the wallet option in the tokens screen (only with CYRUS_WALLET_PAY and a host wallet). */
async function walletOffer(userId: string): Promise<TokenState["wallet"]> {
  const w = getHost().billing.wallet;
  if (!walletPayEnabled() || !w) return null;
  const nxeon = (process.env.APP_URL || "https://nxeon.cloud").replace(/\/+$/, "");
  return { balanceCents: await w.balance(userId).catch(() => null), addFundsUrl: `${nxeon}/dashboard/billing` };
}

export async function buildTokenState(user: User, opts: { reconcile?: boolean } = {}): Promise<TokenState> {
  const cfg = await loadTokenConfig();
  const active = await tokensActiveFor(user, cfg);
  if (active) await ensureStarterTokens(user, cfg);
  if (active && opts.reconcile !== false) await maybeReconcileUser(user.id);
  const now = new Date();
  const [sum, plan, acct, prices] = await Promise.all([
    tokenSummary(user.id, now),
    db.cyrusPlan.findUnique({ where: { userId: user.id } }),
    db.cyrusTokenAccount.findUnique({ where: { userId: user.id }, select: { tierOverride: true, tierOverrideUntil: true } }),
    active && stripeConfigured() ? planPrices(cfg) : Promise.resolve({ katara: null, saka: null, all: null } as Awaited<ReturnType<typeof planPrices>>),
  ]);
  const tier = effectiveTier({ plan, override: acct?.tierOverride, overrideUntil: acct?.tierOverrideUntil, now, cfg });
  const planActive = !!plan && effectiveTier({ plan, now, cfg }) !== "free";
  return {
    active,
    enforce: cfg.enforce,
    balance: sum.balance,
    reserved: sum.reserved,
    available: sum.available,
    lowBalance: cfg.lowBalance,
    nextExpiry: sum.nextExpiry,
    tier,
    models: modelsFor(tier),
    plan: plan ? {
      tier: plan.tier as PlanTier, priceTier: plan.priceTier as PlanTier, status: plan.status,
      currentPeriodEnd: plan.currentPeriodEnd?.toISOString() ?? null, cancelAtPeriodEnd: plan.cancelAtPeriodEnd, active: planActive,
    } : null,
    plans: PLAN_TIERS.map((t) => ({
      tier: t, name: TIER_LABEL[t], priceCents: prices[t]?.unitAmount ?? cfg.plan.cents[t], tokens: cfg.plan.tokens[t], models: TIER_MODELS[t], purchasable: !!prices[t], games: cfg.plan.games[t],
    })),
    topup: { enabled: cfg.topup.enabled, minCents: cfg.topup.minCents, maxCents: cfg.topup.maxCents, tokensPerUsd: cfg.topup.tokensPerUsd },
    wallet: await walletOffer(user.id),
    reserve: cfg.reserve,
    rolloverMonths: cfg.plan.rolloverMonths,
    frozen: sum.frozen,
    rules: { plan: rolloverRulesCopy(cfg), servers: serverGrantRulesCopy(cfg) },
    payments: stripeConfigured(),
  };
}

export async function buildHistory(userId: string, before?: string | null): Promise<TokenHistory> {
  const { rows, more } = await ledgerPage(userId, { take: 30, before });
  return {
    more,
    rows: rows
      // A hold and its settle are one event for the customer: show the settle (it carries the hold).
      .filter((r) => r.kind !== "reserve" || !rows.some((x) => x.buildId === r.buildId && (x.kind === "spend" || x.kind === "release")))
      .map((r) => ({
        id: r.id, kind: r.kind, delta: r.delta, at: r.createdAt.toISOString(), source: r.source, model: r.model, buildId: r.buildId,
        hold: (r.meta as { hold?: number } | null)?.hold ?? null,
        label: historyLabel(r),
      })),
  };
}

// Who takes part in the Cyrus token economy. Server only.
//
// Until the owner launches (Setting cyrus_tok_live = true) ONLY private-preview accounts
// (lib/preview-access.ts feature "modbuilder", the same list that can open Cyrus) earn
// grants, see the checkout line or the balance. Everyone else: nothing happens and
// nothing is shown. Fails closed (a settings/DB error = not active).
import { getHost } from "../host";
import { cyrusDb as db } from "../db";
import { loadTokenConfig, type TokenConfig } from "./config";
import { effectiveTier } from "./economy";
import type { TokenTier } from "./config";

/**
 * In the token economy: the owner has launched it for everyone (cyrus_tok_live), the account is on the
 * private preview list, OR the account has EVER held tokens (an account row exists). Once an account has had
 * tokens it stays in the economy for good, even at a zero balance, so its balance stays pinned in the portal.
 */
export async function tokensActiveFor(user: { id?: string | null; email?: string | null } | null | undefined, cfg?: TokenConfig): Promise<boolean> {
  if (!user?.email) return false;
  try {
    const c = cfg ?? (await loadTokenConfig());
    if (c.live) return true;
    if (await getHost().access.isPreviewUser(user, "modbuilder")) return true;
    if (user.id) return !!(await db.cyrusTokenAccount.findUnique({ where: { userId: user.id }, select: { userId: true } }));
    return false;
  } catch {
    return false;
  }
}

export async function tokensActiveForUserId(userId: string, cfg?: TokenConfig): Promise<boolean> {
  const u = await getHost().users.get(userId).catch(() => null);
  return tokensActiveFor(u, cfg);
}

/** The account's model entitlement now (plan + admin override). */
export async function tierOf(userId: string, cfg?: TokenConfig, now = new Date()): Promise<TokenTier> {
  const c = cfg ?? (await loadTokenConfig());
  const [plan, acct] = await Promise.all([
    db.cyrusPlan.findUnique({ where: { userId } }),
    db.cyrusTokenAccount.findUnique({ where: { userId }, select: { tierOverride: true, tierOverrideUntil: true } }),
  ]);
  // CYRUS_ENTITLEMENT_MIRROR (standalone Cyrus): a mirrored plan Nxeon has not confirmed recently counts as none (fail closed)
  const gated = process.env.CYRUS_ENTITLEMENT_MIRROR === "1" ? await (await import("./entitlement")).gateMirroredPlan(userId, plan, process.env, now) : plan;
  return effectiveTier({ plan: gated, override: acct?.tierOverride, overrideUntil: acct?.tierOverrideUntil, now, cfg: c });
}
// The Cyrus public launch is TWO switches that must move together: the studio (cyrus_studio_public_enabled)
// and the token economy (cyrus_tok_live). Studio open to the public while tokens are off means builds that nobody
// meters or pays for, and (before this guard) a free choice of any model. This pure module is the one place that
// decides what the pair means; everything that opens Cyrus to non-preview accounts must go through it.
// Pure (unit-tested without any framework imports).

export type LaunchState =
  /** Studio flag off: only the private preview can build. (Tokens may or may not be live; that is fine.) */
  | "closed"
  /** Both on: the public may build, metered by tokens. */
  | "public"
  /** Studio flag on but tokens off: INVALID. Non-preview accounts are refused (fail closed). */
  | "unmetered";

export function launchState(o: { studioPublic: boolean; tokensLive: boolean }): LaunchState {
  if (!o.studioPublic) return "closed";
  return o.tokensLive ? "public" : "unmetered";
}

/** True only when the public may open the studio and build. */
export const publicMayBuild = (o: { studioPublic: boolean; tokensLive: boolean }): boolean => launchState(o) === "public";

/** The message an operator sees when the flags are in the invalid combination. */
export const UNMETERED_NOTICE =
  "Cyrus studio is set public but the token economy is off: the public is blocked until cyrus_tok_live is on too (they must be turned on together).";
/**
 * PRIVATE PREVIEW GATE — one tiny helper shared by every unreleased customer
 * feature ("dedicated", "modbuilder"). Keep this file IDENTICAL on every branch
 * that carries it: it has no feature-specific imports.
 *
 * Who is allowed: the accounts whose email is in the allowlist for that feature.
 *   1. Setting `preview_access_emails_<feature>` (comma-separated), if that row exists;
 *   2. else Setting `preview_access_emails` (shared by every feature), if that row exists;
 *   3. else DEFAULT_PREVIEW_EMAILS below (the owner's own customer account).
 * An empty Setting value means "nobody". Matching is case-insensitive on the
 * account's email. A DB error fails CLOSED (nobody is a preview user).
 *
 * Callers decide what "not allowed" looks like (normally `notFound()`, so the
 * feature is indistinguishable from a route that does not exist).
 */
import { getSetting } from "./settings";

export const PREVIEW_FEATURES = ["dedicated", "modbuilder"] as const;
export type PreviewFeature = (typeof PREVIEW_FEATURES)[number];

export const PREVIEW_ACCESS_SETTING = "preview_access_emails";
export const DEFAULT_PREVIEW_EMAILS = ["nicholas.sj.albanese@gmail.com"];

/** Sentinel: getSetting returns it only when no Setting row exists. */
const UNSET = "\u0000unset";

export function parsePreviewEmails(raw: string | null | undefined): string[] {
  return (raw ?? "")
    .split(/[,\s;]+/)
    .map((e) => e.trim().toLowerCase())
    .filter((e) => e.includes("@"));
}

/** Pure decision (unit-tested). */
export function emailInPreviewList(email: string | null | undefined, list: readonly string[]): boolean {
  const e = (email ?? "").trim().toLowerCase();
  return !!e && list.some((x) => x.trim().toLowerCase() === e);
}

export async function previewAllowlist(feature: PreviewFeature): Promise<string[]> {
  if (!(PREVIEW_FEATURES as readonly string[]).includes(feature)) return [];
  const own = await getSetting(`${PREVIEW_ACCESS_SETTING}_${feature}`, UNSET);
  if (own !== UNSET) return parsePreviewEmails(own);
  const shared = await getSetting(PREVIEW_ACCESS_SETTING, UNSET);
  if (shared !== UNSET) return parsePreviewEmails(shared);
  return [...DEFAULT_PREVIEW_EMAILS];
}

/** True only for a signed-in account on the feature's allowlist. Never throws. */
export async function isPreviewUser(
  user: { email?: string | null } | null | undefined,
  feature: PreviewFeature,
): Promise<boolean> {
  if (!user?.email) return false;
  try {
    return emailInPreviewList(user.email, await previewAllowlist(feature));
  } catch {
    return false; // fail CLOSED
  }
}

