import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import dns from "node:dns/promises";
import { latestRuns } from "./eval-run.mjs";
import { buildResult, ledgerFacts, nginxAppPrefixes, renderTable, stripeKeyMode } from "./launch-eval.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(HERE, "../../..");
const E = process.env;
const ENVF = E.ENVF || "/opt/nxeon/.env";
const SVC = E.SVC || "http://127.0.0.1:7340";
const CYRUS = E.CYRUS_PUBLIC_URL || "https://cyrus.my";
const NXEON = E.CYRUS_NXEON_URL || "https://nxeon.cloud";
const STATE = E.CYRUS_STATE_DIR || "/var/lib/cyrus";
const LIB = E.CYRUS_LIBRARY_DIR || "/tank/cyrus-library-staging";

const sh = (cmd, args, t = 15000, input) => { try { return execFileSync(cmd, args, { encoding: "utf8", timeout: t, stdio: ["pipe", "pipe", "pipe"], input }).trim(); } catch (e) { return { error: String(e.stderr || e.message || e).trim().split("\n").slice(-2).join(" ").slice(0, 200) }; } };
const str = (v) => (typeof v === "string" ? v : "");
const readText = (p) => { try { return readFileSync(p, "utf8"); } catch { return null; } };
const mtimeMin = (p, now) => { try { return Math.round((now - statSync(p).mtimeMs) / 60000); } catch { return null; } };
const sha256 = (p) => { try { return createHash("sha256").update(readFileSync(p)).digest("hex"); } catch { return null; } };

function envFile(p) {
  const out = {}; const t = readText(p); if (!t) return out;
  for (const l of t.split("\n")) { const m = /^([A-Z0-9_]+)=(.*)$/.exec(l.trim()); if (m) out[m[1]] = m[2].replace(/^["']|["']$/g, ""); }
