async function authenticate(req: Request, op: Operation, cfg: ApiV1Config, deps: V1Deps, ctx: Ctx): Promise<AuthOut> {
  const no = (res: Response): AuthOut => ({ ok: false, res });
  const h = req.headers.get("authorization") ?? "";
  const bearer = (h.startsWith("Bearer ") ? h.slice(7) : "").trim();
  const personal = await authenticatePersonal(bearer, op, cfg, deps, ctx);
  if (personal) return personal;
  const tok = parseServiceToken(bearer);
  // unknown key and wrong secret look the same to the caller
  const key = tok ? cfg.keys.find((k) => k.id === tok.keyId) ?? null : null;
  if (!tok || !key || !safeEqual(sha256Hex(tok.secret), key.sha256)) return no(fail(ctx, 401, "unauthorized", "a valid Cyrus service token is required", undefined, { "www-authenticate": 'Bearer realm="cyrus-api-v1"' }));
  const missing = op.scopes.filter((s) => !key.scopes.includes(s));
  if (missing.length) return no(fail(ctx, 403, "forbidden_scope", `this token lacks ${missing.join(", ")}`));
  const rl = deps.rateLimit(`cyrus-api-v1:${key.id}`, key.rpm, 60_000);
  ctx.headers["ratelimit-limit"] = String(key.rpm);
  ctx.headers["ratelimit-remaining"] = String(Math.max(0, rl.remaining));
  if (!rl.ok) return no(fail(ctx, 429, "rate_limited", "too many requests for this token", undefined, { "retry-after": String(Math.max(1, rl.retryAfterSec)) }));
  if (!op.subject) return { ok: true, caller: { key, subject: null } };
  // the subject id is a platform account id: only a client the owner named as an identity source may assert one
  if (!(cfg.identityClients ?? []).includes(key.client)) return no(fail(ctx, 403, "subject_not_allowed", "this client may not act for an account"));
  const raw = req.headers.get("cyrus-subject");
  if (!raw) return no(fail(ctx, 400, "subject_required", "this operation acts for one account: send the Cyrus-Subject assertion"));
  const v = verifySubjectAssertion(raw, { client: key.client, keys: cfg.subjectKeys, nowMs: deps.now().getTime(), replay: deps.replay });
  if (!v.ok) return no(fail(ctx, 401, v.code, v.message));
  return { ok: true, caller: { key, subject: v.claims.sub } };
}

