/** Parse the guard's one-line answer. null = unreadable (the caller applies its fail-open/closed policy). */
function parseGuard(text) {
  const m = String(text || "").trim().toLowerCase().match(/\b(allow|refuse)\b\s*[:\-]?\s*(simple|standard|complex|injection|escape|malware|obfuscation)?/);
  if (!m) return null;
  if (m[1] === "refuse") return { verdict: "refuse", code: m[2] && !/^(simple|standard|complex)$/.test(m[2]) ? m[2] : "policy" };
  return { verdict: "allow", class: /^(simple|standard|complex)$/.test(m[2] || "") ? m[2] : null };
}

// Cyrus recipe memory (MB_RECIPES=1 only): the same guard call also names up to two archetypes from a CLOSED list (the archetypes
// the verified recipes cover; recipes.js guardArchetypes()), about +10 output tokens. Off = GUARD_PROMPT is used unchanged.
function guardPromptWithArchetypes(ids) {
  if (!ids || !ids.length) return GUARD_PROMPT;
  return GUARD_PROMPT.replace(/Answer with exactly one line and nothing else:[^\n]*$/, `Answer with exactly two lines and nothing else. Line 1: ALLOW simple|standard|complex   or   REFUSE injection|escape|malware|obfuscation
Line 2 (only after ALLOW): ARCHETYPES: up to two ids from this list that the request is mainly about, comma separated, or none: ${ids.join(", ")}`);
}

/** The archetype ids on the guard's second line, kept only when they are in the closed list. */
function parseGuardArchetypes(text, allowed) {
  const m = String(text || "").match(/archetypes?\s*:\s*([a-z0-9_,\s-]+)/i);
  if (!m) return [];
  const ok = new Set(allowed || []);
  return [...new Set(m[1].split(/[\s,]+/).map((x) => x.trim().toLowerCase()).filter((x) => ok.has(x)))].slice(0, 2);
}

