/** The prompt the studio opens with: concrete facts, no promises. */
export function serverPrefill(c: ServerContext): string {
  const facts = [c.version ? `Minecraft ${c.version}` : "Minecraft", c.loader ? c.loader.charAt(0).toUpperCase() + c.loader.slice(1) : null, c.ramMB ? `${Math.round(c.ramMB / 1024)} GB RAM` : null].filter(Boolean).join(", ");
