/** From a Cyrus project: its NxLabs listing (the page is created on the spot if it doesn't exist yet). */
export async function openInNxLabs(projectIdOrBuildId: string): R<{ href: string; editHref: string; slug: string }> {
  const { user, allowed } = await requireViewer("read");
  if (!allowed || !user) return NF;
  const page = await ownProjectPage(projectIdOrBuildId, user);
  if (!page) return { error: "This mod gets its NxLabs page when its first version finishes building." };
  return { ok: true, href: `/dashboard/nxlabs/cyrus/${page.slug}`, editHref: `/dashboard/nxlabs/cyrus/${page.slug}/edit`, slug: page.slug };
}

