export type WriteOperationId = "createProject" | "createBuild" | "createInstall" | "getInstall" | "putConfigValues" | "contributeLibraryAsset";
export type Outcome<T> = { ok: true; status?: number; value: T } | { ok: false; status: number; code: string; message: string; detail?: Record<string, unknown> };
export type InstallView = { id: string; buildId: string | null; serverId: string | null; status: "queued" | "running" | "succeeded" | "failed" | "rolledback"; error: string | null; createdAt: string; finishedAt: string | null; delivery?: unknown };
export type ApiAuditEvent = { subject: string; client: string; keyId: string; op: WriteOperationId; target: string | null; status: number; requestId: string; replay: boolean };

export type V1WriteDeps = {
  idempotency: IdempotencyStore;
  audit(e: ApiAuditEvent): Promise<void>;
  /** The Mod Builder access rule (preview list / public launch + verified email) for one account. */
  mayUseCyrus(subject: string): Promise<boolean>;
  createProject(subject: string, input: { game: string; title: string | null }): Promise<Outcome<ProjectRow>>;
  createBuild(subject: string, input: { prompt: string; mcVersion: string; baseBuildId?: string; changeRequest?: string; model?: string }): Promise<Outcome<BuildRow>>;
  requestInstall(subject: string, input: z.output<typeof CreateInstallZ>, idempotencyKey: string): Promise<Outcome<InstallView | Record<string, unknown>>>;
  installStatus(subject: string, installId: string): Promise<Outcome<InstallView>>;
  configValues(subject: string, input: { rootBuildId: string; action: "preview" | "save"; values: Record<string, unknown>; expectedHeadId?: string; message?: string }): Promise<Outcome<unknown>>;
  contribute(subject: string, input: z.output<typeof ContributeAssetZ>): Promise<Outcome<{ outcome: string; ref: string | null; reason: string | null }>>;
};

export type WriteCaller = { key: { id: string; client: string }; subject: string | null };
export type WriteArgs = {
  req: Request; url: URL; params: Record<string, string>; caller: WriteCaller; ctx: Ctx; now: () => Date;
  writes: V1WriteDeps; body: string;
  getProject(id: string): Promise<ProjectRow | null>;
  views: { project(p: ProjectRow): unknown; build(b: BuildRow): unknown };
};

