// Cyrus INTAKE-GUARD refusal log + false-positive review queue (services/modbuilder/route.js GUARD_PROMPT).
//
// Why: the guard is an LLM call (Haiku) that refuses a request before the main model sees it. It has refused real, harmless
// prompts (the dungeon "bosses" prompt was refused as `escape`; ChunkMirror change requests and a music-disc prompt earlier).
// Every refusal is recorded here so a human can mark it a FALSE POSITIVE and the guard prompt can be tuned against real
// text (scripts/cyrus/guard-replay.mjs, docs/cyrus/15-learning-loop.md).
//
// Privacy: the prompt TEXT is kept ONLY in this admin-audit store (CyrusGuardRefusal.promptText) and is nulled
// GUARD_TEXT_RETENTION_DAYS (30) after the refusal by the worker sweep. It is never copied into learning data, candidates,
// logs or notifications. What survives the purge: the hash, the class, the build id, the verdict of the review.
// Server only. Never throws into the build path (recordGuardRefusal).
import { createHash } from "node:crypto";
import { cyrusDb } from "../db";

export const GUARD_TEXT_RETENTION_DAYS = 30;
export const GUARD_STATUSES = ["new", "false_positive", "correct", "dismissed"] as const;
export type GuardStatus = (typeof GUARD_STATUSES)[number];
export const GUARD_CLASSES = ["injection", "escape", "malware", "obfuscation", "policy", "other"] as const;
export type GuardClass = (typeof GUARD_CLASSES)[number];
const DAY = 86_400_000;

/** Whitespace-normalised, lowercased: the same request typed twice hashes the same. */
export const normalizePrompt = (t: string) => t.replace(/\s+/g, " ").trim().toLowerCase();
export const promptHash = (t: string) => createHash("sha256").update(normalizePrompt(t)).digest("hex").slice(0, 32);

/** "guard:escape" (ModBuild.result.errorDetail) -> "escape"; anything else refused -> "other". */
export function refusalClassOf(errorDetail: unknown): GuardClass {
  const m = /guard:([a-z_-]+)/i.exec(String(errorDetail ?? ""));
  const c = (m?.[1] ?? "").toLowerCase();
  return (GUARD_CLASSES as readonly string[]).includes(c) ? (c as GuardClass) : "other";
}

export type RefusedBuild = {
  id: string; userId: string; status: string; errorCode: string | null;
  prompt: string; changeRequest?: string | null; baseBuildId?: string | null;
  result?: unknown;
};

/** The fields a refusal row stores; pure so tests can pin the shape (and that no text leaks outside promptText). */
export function refusalRow(b: RefusedBuild, now: Date = new Date()) {
  const detail = (b.result as { errorDetail?: unknown } | null)?.errorDetail;
  const change = !!b.baseBuildId && !!b.changeRequest;
  const text = change ? `${b.prompt}\n${b.changeRequest}` : b.prompt;
  const guardVersion = (b.result as { guard?: { version?: string } } | null)?.guard?.version ?? null;
  return {
    buildId: b.id, userId: b.userId, promptHash: promptHash(text), refusalClass: refusalClassOf(detail), kind: change ? "change" : "fresh",
    guardVersion: guardVersion ? String(guardVersion).slice(0, 40) : null,
    promptText: text.slice(0, 8000), status: "new" as GuardStatus,
    purgeAt: new Date(now.getTime() + GUARD_TEXT_RETENTION_DAYS * DAY),
  };
}

/** Record a refusal (idempotent per build). Called from syncBuild when a build settles `failed` with errorCode `refused`. */
export async function recordGuardRefusal(b: RefusedBuild, now: Date = new Date()): Promise<boolean> {
  if (b.status !== "failed" || b.errorCode !== "refused") return false;
  try {
    const data = refusalRow(b, now);
    await cyrusDb.cyrusGuardRefusal.upsert({ where: { buildId: b.id }, create: data, update: {} });
    return true;
  } catch (e) {
    console.error("[cyrus-guard] refusal not recorded", b.id, (e as Error).message);
    return false;
  }
}

/** The retention sweep: null the text of every row past its purgeAt. Returns how many rows were scrubbed. */
export async function purgeGuardRefusalText(now: Date = new Date()): Promise<number> {
  const r = await cyrusDb.cyrusGuardRefusal.updateMany({ where: { purgeAt: { lte: now }, promptText: { not: null } }, data: { promptText: null } });
  return r.count;
}

export type RefusalView = {
  id: string; buildId: string; userId: string; promptHash: string; refusalClass: string; kind: string; guardVersion: string | null;
  /** null once purged */
  promptText: string | null; status: GuardStatus; reviewedBy: string | null; reviewedAt: string | null; note: string | null;
  createdAt: string; purgeAt: string; sameHashCount: number;
};

export async function listGuardRefusals(o: { status?: GuardStatus | "open"; take?: number } = {}): Promise<RefusalView[]> {
  const where = o.status === "open" || !o.status ? { status: "new" } : { status: o.status };
  const rows = await cyrusDb.cyrusGuardRefusal.findMany({ where, orderBy: { createdAt: "desc" }, take: Math.min(Math.max(o.take ?? 50, 1), 200) });
  const hashes = [...new Set(rows.map((r) => r.promptHash))];
  const counts = hashes.length ? await cyrusDb.cyrusGuardRefusal.groupBy({ by: ["promptHash"], where: { promptHash: { in: hashes } }, _count: { _all: true } }) : [];
  const by = new Map(counts.map((c) => [c.promptHash, c._count._all]));
  return rows.map((r) => ({
    id: r.id, buildId: r.buildId, userId: r.userId, promptHash: r.promptHash, refusalClass: r.refusalClass, kind: r.kind, guardVersion: r.guardVersion,
    promptText: r.promptText, status: r.status as GuardStatus, reviewedBy: r.reviewedBy, reviewedAt: r.reviewedAt?.toISOString() ?? null, note: r.note,
    createdAt: r.createdAt.toISOString(), purgeAt: r.purgeAt.toISOString(), sameHashCount: by.get(r.promptHash) ?? 1,
  }));
}

export async function reviewGuardRefusal(id: string, status: GuardStatus, by: string, note?: string | null, now: Date = new Date()): Promise<boolean> {
  if (!(GUARD_STATUSES as readonly string[]).includes(status)) return false;
  const r = await cyrusDb.cyrusGuardRefusal.updateMany({ where: { id }, data: { status, reviewedBy: by.slice(0, 80), reviewedAt: now, note: note ? note.slice(0, 500) : null } });
  return r.count > 0;
}

export type GuardStats = { windowDays: number; refused: number; byClass: Record<string, number>; falsePositive: number; correct: number; open: number; builds: number; refusalRatePct: number | null };

/** Counts for the learning tab and the daily beta report (no text). */
export async function guardRefusalStats(windowDays = 7, now: Date = new Date()): Promise<GuardStats> {
  const since = new Date(now.getTime() - windowDays * DAY);
  const [rows, builds] = await Promise.all([
    cyrusDb.cyrusGuardRefusal.groupBy({ by: ["refusalClass", "status"], where: { createdAt: { gte: since } }, _count: { _all: true } }),
    cyrusDb.modBuild.count({ where: { createdAt: { gte: since } } }),
  ]);
  const byClass: Record<string, number> = {};
  let refused = 0, falsePositive = 0, correct = 0, open = 0;
  for (const r of rows) {
    const n = r._count._all;
    refused += n; byClass[r.refusalClass] = (byClass[r.refusalClass] ?? 0) + n;
    if (r.status === "false_positive") falsePositive += n; else if (r.status === "correct") correct += n; else if (r.status === "new") open += n;
  }
  return { windowDays, refused, byClass, falsePositive, correct, open, builds, refusalRatePct: builds ? Math.round((refused / builds) * 1000) / 10 : null };
}
