// Cyrus notification copy + email templates (r40). PURE, client-safe. One function per event builds the in-app title /
// body / link and the email (subject, HTML, plain text) from the event's data only (no invented figures).
// Visual language: the cyrus.my landing (near-black #050508, white type, electric blue #3d7bff -> violet #8b5cff
// accents), table layout + inline styles so it renders in every mail client, dark by design.
import type { NotifyEvent } from "./events";

const STUDIO = "/dashboard/cyrus"; // CYRUS_STUDIO_PATH (lib/cyrus/public-gate.ts); cyrus.my serves the same app

export type Rendered = { title: string; body: string; href: string | null; subject: string; html: string; text: string };
export type RenderCtx = { appBase: string; prefsUrl: string };

const esc = (s: unknown) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
const str = (d: Record<string, unknown>, k: string, max = 120) => String(d[k] ?? "").replace(/[\r\n]+/g, " ").slice(0, max);
const safeHref = (base: string, path: string) => (/^\/[A-Za-z0-9/_?=&.%-]*$/.test(path) ? `${base.replace(/\/$/, "")}${path}` : base);

function copy(ev: NotifyEvent, d: Record<string, unknown>): { title: string; body: string; path: string | null; cta: string } {
  const name = str(d, "name") || "your mod";
  switch (ev) {
    case "build.finished": {
      const ok = d.status === "succeeded";
      return { title: ok ? `${name} is built` : `${name} did not build`, body: ok ? "Your build finished. Check its Test Flight result, then install it on a server or keep changing it." : `The build stopped${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} The build page shows what happened and what was charged. A build that fails on our side is not charged.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: ok ? "Open the build" : "See what happened" };
    }
    case "install.result": {
      const ok = d.ok === true;
      return { title: ok ? `${name} is on ${str(d, "server") || "your server"}` : `${name} was not installed`, body: ok ? (d.restartRequired ? "Installed. Restart the server to load it." : "Installed and loaded.") : `The install did not finish${str(d, "reason") ? `: ${str(d, "reason", 200)}` : "."} Cyrus undid its changes where it could. Open Cyrus to confirm the state of your server, or roll back to your previous build.`, path: STUDIO, cta: "Open Cyrus" };
    }
    case "mod.outdated":
      return { title: `${name} may need a rebuild`, body: `${str(d, "game") || "The game"} ${str(d, "version") ? `moved to ${str(d, "version")}` : "was updated"}. Your mod was built for ${str(d, "builtFor") || "an older version"}; rebuild it to keep it working. You see the cost before you rebuild.`, path: d.buildId ? `${STUDIO}/${encodeURIComponent(str(d, "buildId", 64))}` : STUDIO, cta: "Rebuild" };
    case "takedown":
      return { title: `${name} was taken down`, body: `${str(d, "what") || "Content"} was removed${str(d, "reason") ? ` (${str(d, "reason", 200)})` : ""}. Projects that used it keep their own copy and keep working.${d.counterNotice ? " If you believe this is a mistake, you can send a counter-notice by replying to this email." : ""}`, path: STUDIO, cta: "Open Cyrus" };
    case "tokens.low":
      return { title: "Your Cyrus tokens are running low", body: `${str(d, "available") ? `${str(d, "available")} tokens left.` : "Your balance is low."} Top up or change plan to keep building. Your mods and installs are not affected.`, path: STUDIO, cta: "Get tokens" };
  }
}

export function renderNotification(ev: NotifyEvent, data: Record<string, unknown>, ctx: RenderCtx): Rendered {
  const c = copy(ev, data);
  const href = c.path ? safeHref(ctx.appBase, c.path) : null;
  const subject = c.title.slice(0, 120);
  const text = `${c.title}\n\n${c.body}\n\n${href ? `${c.cta}: ${href}\n\n` : ""}Notification settings: ${ctx.prefsUrl}\nCyrus, a Nxeon product.`;
  // Same structure as the Nxeon email shell v2 (lib/email-render.ts wrapEmail2: rounded shell with a header row,
  // hero band with eyebrow + big headline + lead, full-width gradient button, footer), self-contained because this
  // file is a host seam with no Nxeon imports. Keeps the Cyrus palette (near-black, electric blue -> violet).
  const base = ctx.appBase.replace(/\/$/, "");
  const eyebrow = ev === "tokens.low" ? "Tokens" : ev === "takedown" ? "Notice" : ev === "mod.outdated" ? "Heads up" : "Your build";
  const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="dark light"><meta name="supported-color-schemes" content="dark light"><title>${esc(subject)}</title>
<style>@media only screen and (max-width:620px){.cy-pad{padding-left:22px!important;padding-right:22px!important}.cy-h1{font-size:28px!important;line-height:34px!important}}</style></head>
<body bgcolor="#050508" style="margin:0;padding:0;background:#050508;color:#ffffff;font-family:Inter,Segoe UI,Helvetica,Arial,sans-serif;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#050508" style="background:#050508;"><tr><td align="center" style="padding:32px 14px 40px;">
<table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0" bgcolor="#0a0d1c" style="width:100%;max-width:600px;background:#0a0d1c;border:1px solid #1d2442;border-radius:22px;">
<tr><td class="cy-pad" style="padding:24px 40px 20px 40px;border-bottom:1px solid #1a2034;"><a href="${esc(base)}/cyrus" style="text-decoration:none;"><img src="${esc(base)}/email/art/cyrus-logo.png" width="136" height="32" alt="Cyrus" style="display:block;width:136px;height:32px;border:0;color:#ffffff;font-size:18px;font-weight:800;letter-spacing:.14em;"></a></td></tr>
<tr><td class="cy-pad" bgcolor="#0a0d1c" style="padding:42px 40px 14px 40px;background:#0a0d1c;background-image:radial-gradient(ellipse at 100% 0%,#1b2a6b 0%,#0a0d1c 60%);">
<div style="margin:0 0 14px;font-size:13px;line-height:16px;font-weight:700;letter-spacing:1.8px;text-transform:uppercase;color:#9cc0ff;">${esc(eyebrow)}</div>
<h1 class="cy-h1" style="margin:0 0 18px;font-size:34px;line-height:40px;font-weight:800;letter-spacing:-.8px;color:#ffffff;">${esc(c.title)}</h1>
<p style="margin:0;font-size:16px;line-height:26px;color:#cfd3e0;">${esc(c.body)}</p>
</td></tr>
${href ? `<tr><td class="cy-pad" style="padding:22px 40px 36px 40px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr><td align="center" bgcolor="#3d7bff" style="border-radius:12px;background:#3d7bff;background-image:linear-gradient(90deg,#3d7bff,#8b5cff);"><a href="${esc(href)}" style="display:block;padding:17px 20px;border-radius:12px;color:#ffffff;text-decoration:none;font-weight:700;font-size:16px;line-height:20px;">${esc(c.cta)}&nbsp;&#10142;</a></td></tr></table></td></tr>` : `<tr><td style="height:26px;font-size:0;line-height:0;">&nbsp;</td></tr>`}
<tr><td class="cy-pad" align="center" style="padding:0 40px 28px 40px;font-size:12px;line-height:19px;color:#8a8fa3;">You get this because of your <a href="${esc(ctx.prefsUrl)}" style="color:#9cc0ff;">Cyrus notification settings</a>.<br>Cyrus, a Nxeon product.</td></tr>
</table></td></tr></table></body></html>`;
  return { title: c.title.slice(0, 160), body: c.body.slice(0, 500), href, subject, html, text };
}

