/** r44 card top-ups: the envelope for a paid Checkout session (same idemKey `topup:<session>` as the old direct credit). */
export function cardTopupEnvelope(a: { userId: string; sessionId: string; tokens: number; paidCents: number; expiresAt: Date; paymentIntent: string | null; livemode: boolean }, now = new Date()): PurchaseEnvelope {
  return purchaseEnvelope("purchase.completed", a.userId, {
    idemKey: `topup:${a.sessionId}`, kind: "topup", method: "card", tokens: a.tokens, cents: a.paidCents, expiresAt: a.expiresAt.toISOString(),
    note: `Top-up $${(a.paidCents / 100).toFixed(2)}`, sourceRef: a.sessionId, paymentIntent: a.paymentIntent, livemode: a.livemode,
  }, now);
}

/** r44 reconciliation for card top-ups on the event path: a paid session whose event never landed (dead sender row,
 *  lost process) is applied directly, once (same idemKey). Only runs with CYRUS_PURCHASE_EVENTS=1 (direct mode cannot
 *  lose one). `sessions` = recent paid Cyrus top-up sessions from the payment provider. */
export async function reconcileCardTopups(envelopes: PurchaseEnvelope[], minAgeMs = 15 * 60_000, now = new Date()): Promise<{ checked: number; credited: number }> {
  if (!purchaseEventsEnabled()) return { checked: 0, credited: 0 };
  let checked = 0, credited = 0;
  for (const e of envelopes) {
    if (now.getTime() - Date.parse(e.createdAt) < minAgeMs) continue; // give the event path time first
    checked++;
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: e.data.idemKey }, select: { id: true } })) continue;
    if ((await applyPurchaseEvent(e)).applied) credited++;
  }
  return { checked, credited };
}

/** Reconciliation: any referenced wallet charge without a ledger row (and without a refund) is credited. */
export async function reconcileWalletTopups(o: { userId?: string; sinceMs?: number } = {}): Promise<{ checked: number; credited: number }> {
  const w = getHost().billing.wallet;
  if (!walletPayEnabled() || !w?.findByReference) return { checked: 0, credited: 0 };
  const cfg = await loadTokenConfig();
  const moves = await w.findByReference({ userId: o.userId, prefix: "cwt:", sinceMs: o.sinceMs ?? Date.now() - 7 * DAY });
  const refunded = new Set(moves.filter((m) => m.cents > 0 && m.reference.endsWith(":refund")).map((m) => m.reference.slice(0, -":refund".length)));
  let credited = 0, checked = 0;
  for (const m of moves) {
    if (m.cents >= 0 || refunded.has(m.reference) || locks.has(m.reference)) continue;
    checked++;
    if (await db.cyrusTokenLedger.findUnique({ where: { idemKey: m.reference }, select: { id: true } })) continue;
    const cents = -m.cents;
    const r = await applyPurchaseEvent(purchaseEnvelope("purchase.completed", m.userId, {
      idemKey: m.reference, kind: "topup", method: "wallet", tokens: topupTokens(cents, cfg), cents,
      expiresAt: new Date(m.at.getTime() + cfg.topup.expiryDays * DAY).toISOString(), note: `Top-up $${(cents / 100).toFixed(2)} (wallet, reconciled)`,
    }));
    if (r.applied) credited++;
  }

