// Worker sweep for the Cyrus token economy (worker/index.ts "cyrus-tokens", every 5 min).
//  1. Settle holds whose build already finished (a settle that failed in the request path).
//  2. A hold whose build row vanished, or that is older than the build service's own
//     2 h staleness limit, is released (never left reserved forever).
//  3. Expire due lots (keeps the admin liability figure honest).
//  4. Reconcile active plans with Stripe at most hourly (covers a webhook that never came).
import { cyrusDb as db } from "../db";
import { getHost } from "../host";

import { settleBuildTokens } from "./builds";
import { expireDueLots, settleReservation } from "./ledger";
import { reconcileSubscription } from "./billing";

// Stripe is the host's (host.billing.stripe); same rule as lib/stripe stripeConfigured inside Nxeon.
const stripeConfigured = () => !!getHost().billing.stripe?.configured();

const STALE_MS = 3 * 60 * 60 * 1000;

let lastCardReconcile = 0;
export async function sweepCyrusTokens(now = new Date()): Promise<{ settled: number; released: number; expired: number; reconciled: number }> {
  let settled = 0, released = 0, reconciled = 0;
  const held = await db.cyrusTokenReservation.findMany({ where: { status: "held" }, take: 200, orderBy: { createdAt: "asc" } });
  if (held.length) {
    const builds = await db.modBuild.findMany({ where: { id: { in: held.map((h) => h.buildId) } }, select: { id: true, userId: true, status: true, errorCode: true, costUsd: true, cyrus: true } });
    const byId = new Map(builds.map((b) => [b.id, b]));
    for (const h of held) {
      const b = byId.get(h.buildId);
      try {
        if (b && (b.status === "succeeded" || b.status === "failed")) { await settleBuildTokens(b, now); settled++; }
        else if ((!b && now.getTime() - h.createdAt.getTime() > 120_000) || now.getTime() - h.createdAt.getTime() > STALE_MS) { await settleReservation({ buildId: h.buildId, charge: 0, reason: "stale", now }); released++; }
      } catch (e) { console.error("[cyrus-tokens] sweep settle", h.buildId, (e as Error).message); }
    }
  }
  const expired = await expireDueLots(undefined, now).catch(() => 0);
  if (stripeConfigured()) {
    const due = await db.cyrusPlan.findMany({
      // mirrored plans (r38, "nxeon:<user>") belong to Nxeon's Stripe, never this one
      where: { endedAt: null, NOT: { stripeSubscriptionId: { startsWith: "nxeon:" } }, OR: [{ lastSyncAt: null }, { lastSyncAt: { lt: new Date(now.getTime() - 60 * 60_000) } }] },
      take: 25,
    });
    for (const p of due) {
      try { await reconcileSubscription(p.stripeSubscriptionId); reconciled++; } catch (e) { console.error("[cyrus-tokens] reconcile", p.userId, (e as Error).message); }
    }
  }
  // r44: card top-ups on the event path whose event never landed (CYRUS_PURCHASE_EVENTS only; at most every 30 min)
  if (process.env.CYRUS_PURCHASE_EVENTS === "1" && now.getTime() - lastCardReconcile > 30 * 60_000) {
    lastCardReconcile = now.getTime();
    const r = await (await import("./billing")).reconcileCardTopupSessions().catch((e) => { console.error("[cyrus-tokens] card top-up reconcile", (e as Error).message); return null; });
    if (r) reconciled += r.credited;
  }
  // r38 entitlement mirror (standalone Cyrus, CYRUS_ENTITLEMENT_MIRROR=1): re-pull plans Nxeon has not confirmed in 12 h
  if (process.env.CYRUS_ENTITLEMENT_MIRROR === "1") {
    const r = await (await import("./entitlement")).reconcileEntitlements({ now, limit: 50 }).catch((e) => { console.error("[cyrus-tokens] entitlement reconcile", (e as Error).message); return null; });
    if (r) reconciled += r.pulled;
  }
  return { settled, released, expired, reconciled };
}
